import 'dart:convert';
import 'dart:io';

import 'package:path/path.dart' as p;
import 'package:yaml/yaml.dart';

import '../project_layout.dart';
import 'deploy_target.dart';
import 'kamal_images.dart';
import 'kamal_secret_files.dart';
import 'stack.dart';

const kamalGeneratedHeader =
    '# generated by `dartway deploy kamal` — change deploy/config.yaml and regenerate\n';

/// Generates the deployment contract from the project, without reading secrets.
class DwKamalGenerator {
  DwKamalGenerator(this.projectRoot);

  final Directory projectRoot;

  Map<String, String> render() {
    final snippets = Directory(p.join(projectRoot.path, 'deploy/nginx.d'));
    if (snippets.existsSync() &&
        snippets
            .listSync(recursive: true)
            .whereType<File>()
            .any((file) => file.path.endsWith('.conf'))) {
      throw StateError(
        'Native Kamal cannot apply deploy/nginx.d snippets. '
        'Move call quotas to DwServerSettings.callRateLimits and migrate '
        'other ingress policies before generating Kamal destinations.',
      );
    }
    final layout = ProjectLayout.detect(projectRoot);
    final environments = DwDeployTarget.environmentsIn(projectRoot);
    for (final environment in environments) {
      if (!destinations.containsKey(environment)) {
        throw StateError(
          'deploy/config.yaml: unsupported deployment "$environment"; '
          'Kamal destinations are staging (stage) and production (prod).',
        );
      }
    }
    if (environments.isEmpty) {
      throw StateError(
        'deploy/config.yaml: declare staging or production before generating '
        'Kamal configuration. local is not a destination.',
      );
    }
    final targets = [
      for (final environment in environments)
        DwDeployTarget.load(projectRoot: projectRoot, environment: environment),
    ];
    final first = targets.first;
    final owner = githubOwner(first.repo);
    for (final target in targets) {
      if (target.site?.deployed == true) {
        throw StateError(
          "deploy/config.yaml > ${target.environment}: site: "
          "Kamal topology doesn't support this yet. Use deploy run to deploy "
          "a static site.",
        );
      }
      if (!DwDeployTarget.projectNamePattern.hasMatch(target.projectName)) {
        throw StateError(
          'deploy/config.yaml > ${target.environment}: project: '
          '"${target.projectName}" must start with a lower case letter or digit '
          'and contain only lower case letters, digits, "_" and "-". '
          'Set project: explicitly when the repository name does not match.',
        );
      }
      if (githubOwner(target.repo) != owner ||
          target.projectName != first.projectName ||
          target.storage != first.storage) {
        throw StateError(
          'deploy/config.yaml: destinations must share the repository, '
          'project name and service inventory (storage mode).',
        );
      }
    }
    final services = [
      if (first.storage == DwStorageMode.bundled) 'storage',
      'api',
      'web',
    ];
    final files = <String, String>{};
    void yaml(String path, Map<String, Object?> data) {
      files[path] = '$kamalGeneratedHeader${_yaml(data)}';
    }

    for (final service in services) {
      final identity = '${first.projectName}-$service';
      yaml('deploy/kamal/$service.yml', {
        'service': identity,
        'image': '$owner/$identity',
        'minimum_version': '2.12.0',
        'proxy': {
          'ssl': true,
          // The app host reaches this ingress through its nginx. Preserve that
          // chain and let the server stop at the first untrusted peer. The
          // proxy still appends the actual TCP peer to direct API requests.
          if (service == 'api') 'forward_headers': true,
          'run': {
            'version': 'v0.10.2',
            'options': {'sysctl': 'net.ipv4.tcp_congestion_control=bbr'},
          },
          'app_port': switch (service) {
            'api' => 8080,
            'storage' => 9000,
            _ => 80,
          },
          'healthcheck': {'path': service == 'web' ? '/' : '/health'},
          'buffering': {'requests': false, 'responses': false},
        },
        'registry': {
          'server': 'ghcr.io',
          'username': owner,
          'password': ['KAMAL_REGISTRY_PASSWORD'],
        },
        'builder': {
          'arch': 'amd64',
          'dockerfile': switch (service) {
            'api' => '${layout.serverPackage}/Dockerfile',
            'web' => '${layout.flutterPackage}/Dockerfile',
            _ => 'deploy/kamal/storage/Dockerfile',
          },
          'context': service == 'storage' ? 'deploy/kamal/storage' : '.',
        },
        'deploy_timeout': 30,
        'drain_timeout': 30,
        'retain_containers': 5,
        if (service == 'api' &&
            targets.any((target) => target.requiredSecretFiles.isNotEmpty))
          'hooks_path': kamalApiHooksDirectory,
      });
      for (final target in targets) {
        final destination = destinations[target.environment]!;
        final stack = DwStack(
          target: target,
          projectRoot: projectRoot,
          serverPackage: layout.serverPackage,
          flutterPackage: layout.flutterPackage,
        );
        yaml('deploy/kamal/$service.$destination.yml', {
          'servers': {
            'web': {
              'hosts': [target.host],
              if (service == 'storage') 'cmd': '/data',
            },
          },
          'ssh': {'user': target.sshUser},
          if (service == 'storage')
            'volumes': ['$identity-data-$destination:/data'],
          'proxy': {
            'hosts': switch (service) {
              'api' => [target.apiDomain],
              'web' => [target.appDomain],
              _ => [target.storageDomain!],
            },
          },
          if (service == 'api') ...{
            if (target.requiredSecretFiles.isNotEmpty)
              'volumes': [
                for (final name in target.requiredSecretFiles)
                  '${target.runtimeConfigDir}/$name:'
                      '${DwStack.secretFilesDir}/$name:ro',
              ],
            'env': {
              'clear': {
                ...stack.serverEnvironment,
                if (target.database == DwDatabaseMode.bundled)
                  'DW_DATABASE_HOST': '$identity-postgres-$destination',
                'DW_ALLOWED_ORIGINS': stack.appOrigin,
                if (target.storage == DwStorageMode.bundled)
                  'DW_STORAGE_PROVISION': 'true',
              },
              'secret': stack.requiredSecretKeys,
            },
            if (target.database == DwDatabaseMode.bundled)
              'accessories': {
                'postgres': {
                  'service': '$identity-postgres-$destination',
                  'image': 'postgres:17-alpine',
                  'host': target.host,
                  'env': {
                    'clear': {
                      'POSTGRES_DB': stack.databaseName,
                      'POSTGRES_USER': stack.databaseName,
                    },
                    'secret': ['POSTGRES_PASSWORD:DW_DATABASE_PASSWORD'],
                  },
                  'directories': ['postgres:/var/lib/postgresql/data'],
                },
              },
          },
          if (service == 'web')
            'env': {
              'clear': {'DW_API_ORIGIN': stack.apiOrigin},
            },
          if (service == 'storage')
            'env': {
              'clear': {'RUSTFS_CONSOLE_ENABLE': 'false'},
              'secret': [
                'RUSTFS_ACCESS_KEY:DW_STORAGE_ACCESS_KEY',
                'RUSTFS_SECRET_KEY:DW_STORAGE_SECRET_KEY',
              ],
            },
        });
      }
    }
    if (targets.any((target) => target.requiredSecretFiles.isNotEmpty)) {
      files[kamalSecretFilesHookPath] = kamalSecretFilesHook(
        kamalGeneratedHeader,
      );
    }
    if (services.contains('storage')) {
      files['deploy/kamal/storage/Dockerfile'] =
          '${kamalGeneratedHeader}FROM rustfs/rustfs:1.0.0\n';
    }
    yaml('deploy/studio.yml', {
      'services': services,
      'environments': environments.map((env) => destinations[env]).toList(),
      'health': '/health',
      'check': {
        'image': 'ghcr.io/dartway/dartway-check:${checkImageTag(layout)}',
        'args': [
          '--project',
          '/project',
          '--env',
          '{env}',
          '--version',
          '{version}',
        ],
      },
    });
    files['.github/workflows/images.yml'] =
        '$kamalGeneratedHeader${kamalImagesWorkflow(layout, services, '$owner/${first.projectName}', targets.map((target) => target.branch))}';
    return files;
  }

  /// Returns every missing, modified or obsolete generated file; never writes
  /// in check mode, including to a read-only mounted project.
  List<String> generate({bool check = false}) {
    final files = render();
    final obsolete = <String>[];
    final directory = Directory(p.join(projectRoot.path, 'deploy/kamal'));
    if (directory.existsSync()) {
      for (final file
          in directory.listSync(recursive: true).whereType<File>()) {
        final relative = p.relative(file.path, from: projectRoot.path);
        if (!files.containsKey(relative) &&
            _isGenerated(file.readAsStringSync())) {
          obsolete.add(relative);
        }
      }
    }
    final stale = <String>[...obsolete];
    for (final entry in files.entries) {
      final file = File(p.join(projectRoot.path, entry.key));
      final executable = entry.key == kamalSecretFilesHookPath;
      final current =
          file.existsSync() &&
          file.readAsStringSync() == entry.value &&
          (!executable ||
              Platform.isWindows ||
              file.statSync().mode & 0x49 != 0);
      if (current) continue;
      stale.add(entry.key);
      if (!check) {
        file.parent.createSync(recursive: true);
        file.writeAsStringSync(entry.value);
        if (executable && !Platform.isWindows) {
          final result = Process.runSync('chmod', ['755', file.path]);
          if (result.exitCode != 0) {
            throw StateError(
              'Cannot make ${entry.key} executable: ${result.stderr}',
            );
          }
        }
      }
    }
    if (!check) {
      for (final path in obsolete) {
        File(p.join(projectRoot.path, path)).deleteSync();
      }
    }
    return stale..sort();
  }

  static bool _isGenerated(String text) =>
      text.startsWith(kamalGeneratedHeader) ||
      text.startsWith('#!/usr/bin/env ruby\n$kamalGeneratedHeader');

  static const destinations = {'staging': 'stage', 'production': 'prod'};

  static String githubOwner(String repo) {
    final match = RegExp(
      r'^(?:git@github\.com:|https://github\.com/)([\w-]+)/[\w.-]+(?:\.git)?$',
    ).firstMatch(repo);
    if (match == null) {
      throw StateError(
        'deploy/config.yaml: expected a GitHub repository, got "$repo".',
      );
    }
    return match[1]!.toLowerCase();
  }

  static String checkImageTag(ProjectLayout layout) {
    final lock = File(p.join(layout.flutterPackageDir.path, 'pubspec.lock'));
    if (!lock.existsSync()) {
      throw StateError(
        '${lock.path}: resolve dartway_cli before generating Kamal configuration.',
      );
    }
    final yaml = loadYaml(lock.readAsStringSync());
    final packages = yaml is YamlMap ? yaml['packages'] : null;
    final cli = packages is YamlMap ? packages['dartway_cli'] : null;
    if (cli is! YamlMap)
      throw StateError('${lock.path}: dartway_cli is not resolved.');
    final description = cli['description'];
    switch (cli['source']) {
      case 'git':
        final sha = description is YamlMap ? description['resolved-ref'] : null;
        if (sha is String && RegExp(r'^[a-f0-9]{40}$').hasMatch(sha))
          return sha;
      case 'hosted':
        final version = cli['version'];
        if (version is String &&
            RegExp(r'^\d+\.\d+\.\d+(?:[-+][\w.+-]+)?$').hasMatch(version))
          return version;
      case 'path':
        final path = description is YamlMap ? description['path'] : null;
        if (path is String) {
          final root = p.isAbsolute(path)
              ? path
              : p.join(lock.parent.path, path);
          try {
            final projectTree = Process.runSync('git', [
              '-C',
              layout.root.path,
              'rev-parse',
              '--show-toplevel',
            ]);
            if (projectTree.exitCode == 0) {
              final tree = Directory(
                (projectTree.stdout as String).trim(),
              ).resolveSymbolicLinksSync();
              final cliPath = Directory(root).resolveSymbolicLinksSync();
              if (p.equals(tree, cliPath) || p.isWithin(tree, cliPath)) {
                throw StateError(
                  '${lock.path}: dartway_cli path dependency is inside the '
                  "project's own git work tree. A vendored framework cannot identify "
                  'a published check image. Instead, pin dartway_cli by git ref.',
                );
              }
            }
            final result = Process.runSync('git', [
              '-C',
              root,
              'rev-parse',
              'HEAD',
            ]);
            final sha = (result.stdout as String).trim();
            if (result.exitCode == 0 && RegExp(r'^[a-f0-9]{40}$').hasMatch(sha))
              return sha;
          } on FileSystemException {
            // A missing resolved path gets the same named lock diagnostic.
          } on ProcessException {
            // The caller reports the same named resolution failure as a
            // missing checkout or HEAD, rather than a process stack trace.
          }
        }
    }
    throw StateError(
      '${lock.path}: cannot resolve a check image tag for dartway_cli (${cli['source']}).',
    );
  }
}

String _yaml(Map<String, Object?> map, [int depth = 0]) {
  final indent = '  ' * depth;
  final out = StringBuffer();
  for (final entry in map.entries) {
    out.write('$indent${entry.key}:');
    if (entry.value case final Map<String, Object?> nested
        when nested.isNotEmpty) {
      out.writeln();
      out.write(_yaml(nested, depth + 1));
    } else {
      out.writeln(' ${jsonEncode(entry.value)}');
    }
  }
  return out.toString();
}
